import FreeCAD as App, Part, math

doc = App.newDocument("folding_V2")
grp = {}
def group(name):
    if name not in grp:
        grp[name] = doc.addObject("App::DocumentObjectGroup", name)
    return grp[name]

# Ends may be bevelled, so a part is a prism on a trapezoid section, not a
# box. The section is built in YZ and extruded along X.
def beam(name, area, sx, sy, sz, cx, cy, cz, rot_x_deg, c1_deg=0.0, c2_deg=0.0, pts=None):
    hy, hl = sy/2.0, sz/2.0
    t1 = math.tan(math.radians(c1_deg))
    t2 = math.tan(math.radians(c2_deg))
    if pts is None:
        pts = [(-hy, -hl - hy*t1), (-hy,  hl - hy*t2),
               ( hy,  hl + hy*t2), ( hy, -hl + hy*t1)]
    vs = [App.Vector(-sx/2.0, y, z) for (y, z) in pts]
    wire = Part.makePolygon(vs + [vs[0]])
    solid = Part.Face(wire).extrude(App.Vector(sx, 0.0, 0.0))
    o = doc.addObject("Part::Feature", name)
    o.Shape = solid
    o.Placement = App.Placement(App.Vector(cx, cy, cz),
                                App.Rotation(App.Vector(1,0,0), rot_x_deg))
    group(area).addObject(o)
    return o

